mapper.delete:
DELETE FROM analysis_resource
 WHERE revision_id = #{revisionId}
   AND resource_type IN ('SERVLET_MAPPING', 'FILTER_MAPPING', 'LISTENER')

mapper.select:
SELECT file_id AS "fileId", path AS "path", encoding AS "encoding"
  FROM analysis_file
 WHERE revision_id = #{revisionId}
   AND file_type = #{fileType}
   AND parse_status <> 'SKIPPED'
 ORDER BY path

SELECT method_id AS "methodId", name AS "name", line_start AS "lineStart"
  FROM analysis_method
 WHERE revision_id = #{revisionId}
   AND owner_symbol_id = #{symbolId}
   AND name IN
    #{name}
   AND NOT is_synthetic
   AND NOT is_constructor
 ORDER BY line_start

mapper.update:
UPDATE analysis_symbol
   SET layer = #{layer}, layer_confidence = 'HIGH'
 WHERE revision_id = #{revisionId}
   AND symbol_id = #{symbolId}
   AND layer IS NULL

mapper.delete:
DELETE FROM analysis_relation
 WHERE revision_id = #{revisionId}
   AND relation_type IN ('RENDERS', 'REQUESTS', 'INCLUDES')

mapper.select:
SELECT file_id AS "fileId", path AS "path", encoding AS "encoding"
  FROM analysis_file
 WHERE revision_id = #{revisionId}
   AND language = #{language}
   AND parse_status <> 'SKIPPED'
   AND file_id > #{afterId}
 ORDER BY file_id
 LIMIT #{limit}

SELECT file_id AS "fileId", path AS "path", encoding AS "encoding", file_type AS "fileType"
  FROM analysis_file
 WHERE revision_id = #{revisionId}
   AND file_type IN
    #{fileType}
   AND parse_status <> 'SKIPPED'
   AND file_id > #{afterId}
 ORDER BY file_id
 LIMIT #{limit}

mapper.sql:
 WHERE e.revision_id = #{revisionId}
AND e.endpoint_type = #{endpointType}
AND e.path LIKE '%' || #{path} || '%'
